using System;
using System.Data;
using System.Text;
using System.Security;
using SimsObject;

namespace SimsService
{
    /// <summary>
    /// Nhập / cập nhật thông tin hợp đồng đào tạo theo lớp (WinForm frmThongTinHopDong)
    /// </summary>
    public partial class SIM_StudentContractInfoService
    {
        public static string BuildStudentContractXml(DataTable dtbData)
        {
            if (dtbData == null || dtbData.Rows.Count == 0)
                return "<root></root>";

            StringBuilder sb = new StringBuilder();
            sb.Append("<root>");
            for (int i = 0; i < dtbData.Rows.Count; i++)
            {
                DataRow drw = dtbData.Rows[i];
                if (drw.RowState == DataRowState.Deleted)
                    continue;

                string strContractNo = drw["ContractNo"] == DBNull.Value ? "" : drw["ContractNo"].ToString();
                sb.Append("<item StudentID=\"");
                sb.Append(drw["StudentID"].ToString());
                sb.Append("\" ContractNo=\"");
                sb.Append(SecurityElement.Escape(strContractNo));
                sb.Append("\" />");
            }
            sb.Append("</root>");
            return sb.ToString();
        }

        public static bool Save(string classID, DataTable dtbData, DateTime? startAt, DateTime? finishAt, decimal? fee, string updatedUser, out Exception errorException)
        {
            errorException = null;
            SIM_Student obj = new SIM_Student();
            string strXml = BuildStudentContractXml(dtbData);

            obj.BeginTransaction();
            if (!obj.UpdateContractInfoBatch(classID, startAt, finishAt, fee, strXml, updatedUser))
            {
                errorException = obj.ErrorException;
                obj.RollBackTransaction();
                return false;
            }

            obj.CommitTransaction();
            return true;
        }
    }
}

using System;
using System.Data;
using System.Threading;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using Global;
using Libs;
