namespace StudentManager.Report
{
    /// <summary>
    /// Nhập số hợp đồng, ngày, học phí hợp đồng đào tạo theo lớp
    /// </summary>
    public partial class frmThongTinHopDong : FormBase, IForm
    {
        #region Consts

        public const string PERMISSION_EDIT = "frmThongTinHopDong_Edit";
        public const string PERMISSION_VIEW = "frmThongTinHopDong_View";

        private const string GRID_QUERY_NAME = "SIM_StudentContractInfo_Search";

        #endregion

        #region Variables

        DataTable dtbData = null;
        bool bolIsRefresh = false;
        bool bolAllowEdit = false;
        string strClassID = "";

        #endregion

        #region IForm Members

        private static frmThongTinHopDong _instance = null;

        public static frmThongTinHopDong Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmThongTinHopDong();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmThongTinHopDong()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            bolAllowEdit = UserSession.HasPermission(PERMISSION_EDIT);
            gvData.OptionsBehavior.Editable = bolAllowEdit;
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                uClass.ClassFilter = "ClassType = 0";
                uClass.ScienceFilter = UserSession.GetScienceFilter(PERMISSION_VIEW);

                if (bolIsRefresh)
                    uClass.RefrehData();
                else
                    uClass.InitData();
            }
        }

        private bool IsValidData()
        {
            if (!uClass.IsValidData())
                return false;

            if (uClass.ClassIDEditValue == null || uClass.ClassIDEditValue.ToString() == "")
            {
                MessageManager.Warning("Bạn phải chọn lớp học!");
                uClass.Focus();
                return false;
            }

            return true;
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                SIM_Student obj = new SIM_Student();
                dtbData = obj.SearchContractInfo(uClass.ClassIDEditValue.ToString());

                if (dtbData != null)
                {
                    strClassID = uClass.ClassIDEditValue.ToString();
                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, GRID_QUERY_NAME, bolIsRefresh);
                    gvData.BestFitColumns();

                    FillPanelFromFirstRow();
                    EnablePasteButtons(dtbData.Rows.Count > 0 && bolAllowEdit);
                    btnSave.Enabled = mnuItemSave.Enabled = false;
                    mnuItemExportToExcel.Enabled = dtbData.Rows.Count > 0;
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!\r\n" + (obj.ErrorException != null ? obj.ErrorException.Message : ""));
                }
            }
        }

        private void FillPanelFromFirstRow()
        {
            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                txtContractNo.EditValue = null;
                dateStartAt.EditValue = null;
                dateFinishAt.EditValue = null;
                txtFee.EditValue = null;
                return;
            }

            DataRow drw = dtbData.Rows[0];
            txtContractNo.TextTrim = drw["ContractNo"].ToString();

            if (drw["StartAt"] != DBNull.Value && drw["StartAt"].ToString() != "")
                dateStartAt.EditValue = Convert.ToDateTime(drw["StartAt"]);
            else
                dateStartAt.EditValue = null;

            if (drw["FinishAt"] != DBNull.Value && drw["FinishAt"].ToString() != "")
                dateFinishAt.EditValue = Convert.ToDateTime(drw["FinishAt"]);
            else
                dateFinishAt.EditValue = null;

            if (drw["Fee"] != DBNull.Value && drw["Fee"].ToString() != "")
                txtFee.EditValueDecimal = Convert.ToDecimal(drw["Fee"]);
            else
                txtFee.EditValue = null;
        }

        private void EnablePasteButtons(bool enabled)
        {
            btnSetContractNo.Enabled = enabled;
            btnSetStartAt.Enabled = enabled;
            btnSetFinishAt.Enabled = enabled;
            btnSetFee.Enabled = enabled;
        }

        private void ApplyValueToSelectedRows(string columnName, object value)
        {
            foreach (int i in gvData.GetSelectedRows())
            {
                DataRow drw = gvData.GetDataRow(i);
                if (drw == null)
                    continue;
                drw[columnName] = value == null ? DBNull.Value : value;
            }
            btnSave.Enabled = mnuItemSave.Enabled = true;
        }

        private bool SaveData()
        {
            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                MessageManager.Warning("Không có dữ liệu để lưu!");
                return false;
            }

            if (strClassID == "")
                strClassID = uClass.ClassIDEditValue.ToString();

            DateTime? dtmStartAt = dateStartAt.EditValueDateTime;
            DateTime? dtmFinishAt = dateFinishAt.EditValueDateTime;
            decimal? decFee = txtFee.EditValueDecimal;

            // Đồng bộ ngày / học phí lớp xuống mọi dòng trước khi lưu
            for (int i = 0; i < dtbData.Rows.Count; i++)
            {
                DataRow drw = dtbData.Rows[i];
                drw["StartAt"] = dtmStartAt.HasValue ? (object)dtmStartAt.Value : DBNull.Value;
                drw["FinishAt"] = dtmFinishAt.HasValue ? (object)dtmFinishAt.Value : DBNull.Value;
                drw["Fee"] = decFee.HasValue ? (object)decFee.Value : DBNull.Value;
            }

            Exception objEx = null;
            if (!SIM_StudentContractInfoService.Save(strClassID, dtbData, dtmStartAt, dtmFinishAt, decFee, UserSession.Username, out objEx))
            {
                if (objEx != null)
                    ErrorManager.Error("Việc cập nhật thông tin hợp đồng bị lỗi!\r\n" + objEx.Message);
                else
                    ErrorManager.Error("Việc cập nhật thông tin hợp đồng bị lỗi!");
                return false;
            }

            dtbData.AcceptChanges();
            MessageManager.Information("Cập nhật thông tin hợp đồng thành công!");
            return true;
        }

        #endregion

        #region Form Actions

        private void frmThongTinHopDong_Load(object sender, EventArgs e)
        {
            CheckPermission();
            SetToolTip();
            new Thread(LoadReferenceData).Start();
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (IsValidData())
                new Thread(LoadData).Start();
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            if (!bolAllowEdit)
            {
                MessageManager.Warning("Bạn không có quyền cập nhật!");
                return;
            }

            if (SaveData())
                btnSave.Enabled = mnuItemSave.Enabled = false;
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            new Thread(LoadReferenceData).Start();
            if (IsValidData())
                new Thread(LoadData).Start();
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            gcData.ExportToExcel();
        }

        #endregion

        #region Paste to grid

        private void btnSetContractNo_Click(object sender, EventArgs e)
        {
            ApplyValueToSelectedRows("ContractNo", txtContractNo.TextTrim);
        }

        private void btnSetStartAt_Click(object sender, EventArgs e)
        {
            object objValue = dateStartAt.EditValue != null ? dateStartAt.EditValue : DBNull.Value;
            ApplyValueToSelectedRows("StartAt", objValue == DBNull.Value ? null : objValue);
        }

        private void btnSetFinishAt_Click(object sender, EventArgs e)
        {
            object objValue = dateFinishAt.EditValue != null ? dateFinishAt.EditValue : DBNull.Value;
            ApplyValueToSelectedRows("FinishAt", objValue == DBNull.Value ? null : objValue);
        }

        private void btnSetFee_Click(object sender, EventArgs e)
        {
            object objValue = txtFee.EditValueDecimal.HasValue ? (object)txtFee.EditValueDecimal.Value : DBNull.Value;
            ApplyValueToSelectedRows("Fee", objValue == DBNull.Value ? null : objValue);
        }

        private void gvData_ValidateRow(object sender, DevExpress.XtraGrid.Views.Base.ValidateRowEventArgs e)
        {
            btnSave.Enabled = mnuItemSave.Enabled = bolAllowEdit;
        }

        #endregion
    }
}

