private static string BuildStudentContractXml(DataTable dtbData)
{
    if (dtbData == null || dtbData.Rows.Count == 0)
        return "<root></root>";

    StringBuilder sb = new StringBuilder();
    sb.Append("<root>");
    for (int i = 0; i < dtbData.Rows.Count; i++)
    {
        DataRow drw = dtbData.Rows[i];
        if (drw.RowState == DataRowState.Deleted)
            continue;

        string strContractNo = drw["ContractNo"] == DBNull.Value ? "" : drw["ContractNo"].ToString();
        sb.Append("<item StudentID=\"");
        sb.Append(drw["StudentID"].ToString());
        sb.Append("\" ContractNo=\"");
        sb.Append(SecurityElement.Escape(strContractNo));
        sb.Append("\" />");
    }
    sb.Append("</root>");
    return sb.ToString();
}

