    string strContractNo = drw["ContractNo"].ToString();
    int intDot = strContractNo.LastIndexOf('.');
    if (intDot >= 0 && intDot < strContractNo.Length - 1)
    {
        string strSuffix = strContractNo.Substring(intDot + 1);
        int intDummy;
        if (int.TryParse(strSuffix, out intDummy))
        {
            txtContractNoPrefix.TextTrim = strContractNo.Substring(0, intDot + 1);
            txtContractNoSeq.TextTrim = strSuffix;
        }
        else
        {
            txtContractNoPrefix.TextTrim = strContractNo;
            txtContractNoSeq.TextTrim = "";
        }
    }
    else
    {
        txtContractNoPrefix.TextTrim = strContractNo;
        txtContractNoSeq.TextTrim = "";
    }

