private void btnSetContractNo_Click(object sender, EventArgs e)
{
    if (txtContractNoSeq.TextTrim == "")
    {
        MessageManager.Warning("Bạn phải nhập số thứ tự!");
        txtContractNoSeq.Focus();
        return;
    }

    int intLenOrder = txtContractNoSeq.TextTrim.Length;
    int intStartOrder;
    if (!int.TryParse(txtContractNoSeq.TextTrim, out intStartOrder))
    {
        MessageManager.Warning("Số thứ tự phải là số tự nhiên. Ví dụ: 01!");
        txtContractNoSeq.Focus();
        return;
    }

    string strPrefix = txtContractNoPrefix.TextTrim;
    foreach (int i in gvData.GetSelectedRows())
    {
        DataRow drw = gvData.GetDataRow(i);
        if (drw == null)
            continue;

        string strPad = "0000000000" + intStartOrder.ToString();
        string strSeq = strPad.Substring(strPad.Length - intLenOrder);
        drw["ContractNo"] = strPrefix + strSeq;
        intStartOrder++;
    }

    btnSave.Enabled = mnuItemSave.Enabled = true;
}

